import json
import os
import sys

def load_config(filepath):
    """Load and parse JSON config file."""
    with open(filepath, 'r') as f:
        config = json.load(f)
    return config

def execute_commands(config):
    """Execute system commands based on config values."""
    if 'commands' not in config:
        print("No commands section in config")
        return

    for cmd_name, cmd_string in config['commands'].items():
        print(f"Executing: {cmd_name}")
        # Execute the command string directly from config
        result = os.system(cmd_string)
        if result != 0:
            print(f"Command {cmd_name} failed with code {result}")
        else:
            print(f"Command {cmd_name} completed successfully")

def main():
    if len(sys.argv) < 2:
        print("Usage: config_executor.py <config_file>")
        sys.exit(1)

    config_file = sys.argv[1]
    config = load_config(config_file)
    execute_commands(config)

if __name__ == "__main__":
    main()
